mapper.update:
UPDATE tracking.milestone
   SET state = #{state},
       adopted_by = #{adoptedBy},
       adopted_at = #{adoptedAt}
 WHERE tracking_number = #{trackingNumber}
   AND milestone_no = #{milestoneNo}
   AND state = 'DRAFT'

mapper.select:
SELECT 
  FROM tracking.tracking_record
 WHERE tracking_number = #{trackingNumber}
   AND shipper_company_id = #{shipperCompanyId}

SELECT tracking_number, current_status, original_eta, latest_eta, last_acquired_at, next_expected_at, created_at
  FROM tracking.tracking_record
 WHERE shipper_company_id = #{shipperCompanyId}
 ORDER BY created_at DESC, tracking_number
 LIMIT #{limit}
